CREATE TABLE IF NOT EXISTS vision14_mixes(id TEXT PRIMARY KEY,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',internal_only INTEGER NOT NULL DEFAULT 1,item_count INTEGER NOT NULL DEFAULT 0,duplicate_count INTEGER NOT NULL DEFAULT 0,created_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS vision14_mix_sources(mix_id TEXT NOT NULL,source_id TEXT NOT NULL,rights_status TEXT NOT NULL,sale_eligible INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(mix_id,source_id),FOREIGN KEY(mix_id) REFERENCES vision14_mixes(id) ON DELETE CASCADE,FOREIGN KEY(source_id) REFERENCES vision14_sources(id));
CREATE TABLE IF NOT EXISTS vision14_mix_items(id INTEGER PRIMARY KEY AUTOINCREMENT,mix_id TEXT NOT NULL,canonical_text TEXT NOT NULL,fingerprint TEXT NOT NULL,citations TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(mix_id) REFERENCES vision14_mixes(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS vision13_intake_queue(id INTEGER PRIMARY KEY AUTOINCREMENT,mix_id TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'ready',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(mix_id) REFERENCES vision14_mixes(id));
CREATE INDEX IF NOT EXISTS idx_v14_mix_items_mix ON vision14_mix_items(mix_id,id);
CREATE INDEX IF NOT EXISTS idx_v13_intake_status ON vision13_intake_queue(status,created_at);
